// Host test: the animated CVLT OF BAPH0MAU5 clip that is compiled into the firmware (device/cvlt_clip.h, the owner's radar.vid
// from the MY BAPH0MAU5 pack). A version 1 clip: grey levels drawn in the theme's own colours. The device parses it with the same
// themepack::parseClip a pack's radar.vid goes through, so this holds the generated bytes to that parser.
// Build: make -C sim test_cvlt_clip
#include "../ui/themepack.h"
#include "../device/cvlt_clip.h"
#include <cstdio>
#include <cstring>

static int fails = 0;
static void check(const char* what, bool ok) { printf(ok ? "  ok   %s\n" : "  FAIL %s\n", what); if (!ok) fails++; }

int main() {
    themepack::Clip c{}; char why[64] = "";
    const bool ok = themepack::parseClip(CVLT_CLIP, sizeof CVLT_CLIP, c, why, sizeof why);
    char m[120]; snprintf(m, sizeof m, "the built-in clip is a valid radar.vid (%s)", why);
    check(m, ok);
    check("102 x 102, the size the radar plays", c.w == 102 && c.h == 102);
    check("grey levels: it takes the theme's colours, so no palette of its own", c.pal == nullptr);
    check("a gentle loop: 1 to 30 fps, more than one frame", c.fps >= 1 && c.fps <= 30 && c.frames > 1);
    check("under the size a pack's clip may have", sizeof CVLT_CLIP <= (size_t)themepack::MAX_CLIP);
    const size_t fb = (size_t)(c.w * c.h + 1) / 2;
    bool anyDiff = false, allZero = true;
    for (size_t i = 0; i < fb; i++) { if (c.px[i]) allZero = false; if (c.px[i] != c.px[(size_t)(c.frames / 2) * fb + i]) anyDiff = true; }
    check("the first frame has picture in it", !allZero);
    check("the middle frame differs from the first (it animates)", anyDiff);
    printf("%s\n", fails ? "FAILED" : "all passed");
    return fails ? 1 : 0;
}
